import "server-only";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

import { env } from "@/lib/env";

/**
 * Object storage for uploaded images. Keys look like `org/<orgId>/<uuid>.webp` and are
 * generated by the server, never taken from the client. The local driver writes to
 * UPLOADS_DIR; a Vercel Blob driver with the same interface arrives with deployment.
 */
export interface ObjectStorage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

const KEY = /^org\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.webp$/;

function resolveKey(root: string, key: string): string {
  if (!KEY.test(key)) throw new Error("invalid storage key");
  const full = path.resolve(root, key);
  // Defence in depth against path traversal, even though keys are validated above.
  if (!full.startsWith(path.resolve(root) + path.sep)) throw new Error("invalid storage key");
  return full;
}

export function localStorage(root: string): ObjectStorage {
  return {
    async put(key, body) {
      const file = resolveKey(root, key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, body, { flag: "wx" });
    },
    async get(key) {
      try {
        return await readFile(resolveKey(root, key));
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw err;
      }
    },
    async delete(key) {
      await rm(resolveKey(root, key), { force: true });
    },
  };
}

let instance: ObjectStorage | undefined;

export function storage(): ObjectStorage {
  instance ??= localStorage(env().UPLOADS_DIR);
  return instance;
}

export const mediaUrl = (key: string) => `/api/v1/media/${key.replace(/^org\//, "")}`;
